const items = $input.all();
const normalizedItems = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const headers = item.json.headers || {};

  // ── Détection de la source ────────────────────────────────
  let sourceType = 'unknown';
  let source = 'unknown';

  if (headers['x-github-event']) {
    sourceType = 'github';
    source = 'GitHub';
  } else if (body.sonarqube || body.project?.key) {
    sourceType = 'sonarqube';
    source = 'SonarQube';
  } else if (
    body.event === 'pipeline_failed'   ||
    body.event === 'pipeline_unstable' ||
    body.event === 'pipeline_success'  ||
    body.job !== undefined             ||
    body.jenkins === true
  ) {
    sourceType = 'jenkins';
    source = 'Jenkins';
  }

  // ── Normalisation ─────────────────────────────────────────
  const normalized = {
    incidentId: body.incidentId ||
      `incident-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,

    source,
    sourceType,

    // ── Champs dynamiques — 100% depuis le payload ──────────
    // Chaque projet Jenkins fournit ces valeurs dans son Jenkinsfile
    // n8n ne connaît aucune valeur par défaut
    projectId:  body.project_id  || null,
    backendUrl: body.backend_url || null,

    // ── Métadonnées du pipeline ──────────────────────────────
    repository: body.repository?.full_name ||
                body.repository?.name      ||
                body.project?.key          ||
                body.repo                  ||
                body.job                   || null,

    branch: body.ref?.replace('refs/heads/', '') ||
            body.branch                          ||
            body.git?.branch                     || null,

    commitSha: body.after              ||
               body.head_commit?.id    ||
               body.commit             ||
               body.revision?.sha      || null,

    pullRequestNumber: body.pull_request?.number ||
                       body.number               || null,

    title: body.title ||
           (body.job
             ? `${body.job} - Build #${body.build_number || 'N/A'}`
             : null) ||
           body.head_commit?.message?.split('\n')[0] ||
           body.message ||
           'Untitled Incident',

    description: body.description          ||
                 body.build_url            ||
                 body.head_commit?.message ||
                 body.message              || '',

    severity: body.severity                     ||
              body.rule?.severity?.toLowerCase() ||
              'medium',

    environment: body.environment                ||
                 body.deployment?.environment    ||
                 'production',

    logs: body.logs         ||
          body.console_output ||
          (body.logs_url ? [body.logs_url] : []),

    changedFiles: body.commits?.[0]?.modified ||
                  body.head_commit?.modified   || [],

    // ── Sources spécifiques ──────────────────────────────────
    github:    sourceType === 'github'    ? body : null,
    sonarqube: sourceType === 'sonarqube' ? body : null,

    // ── Jenkins — sections v3.0 ──────────────────────────────
    jenkins: sourceType === 'jenkins' ? {
      event:        body.event        || null,
      job:          body.job          || null,
      build_number: body.build_number || null,
      build_url:    body.build_url    || null,
      logs_url:     body.logs_url     || null,
      status:       body.status       || null,
      severity:     body.severity     || null,
      tests:        body.tests        || {},
      sonar:        body.sonar        || {},
      trivy:        body.trivy        || {},
      owasp:        body.owasp        || {},
      zap:          body.zap          || {},
      docker:       body.docker       || {},
      deploy:       body.deploy       || {},
      nexus:        body.nexus        || {}
    } : null,

    createdAt: new Date().toISOString()
  };

  normalizedItems.push({ json: normalized });
}

return normalizedItems;

const getIncident = () => {
  const sources = ['Normalize Incident Payload', 'Normalize status BLOCKED', 'Normalize status RESOLVED'];
  for (const s of sources) {
    try {
      const d = $(s).first().json;
      if (d) return d;
    } catch(e) {}
  }
  return $input.first().json;
};

const incident = getIncident();

// Les données sont à la racine du payload, pas sous "jenkins"
const jenkins = incident.jenkins || {};
const zapData   = incident.zap   || jenkins.zap   || {};
const owaspData = incident.owasp || jenkins.owasp || {};
const trivyData = incident.trivy || jenkins.trivy || {};
const reports   = incident.reports || jenkins.reports || {};
const reportsAvailable = reports.available || {};

const jobName = incident.job || jenkins.job || incident.repository;

// Lookup Project
const projects = $('Lookup Project').all();
let project = null;
for (const item of projects) {
  const p = item.json;
  if (Array.isArray(p)) {
    project = p.find(x => x.jenkinsJobName === jobName) || p[0];
    break;
  }
  if (p.jenkinsJobName === jobName) { project = p; break; }
}
if (!project && projects.length > 0) {
  const first = projects[0].json;
  project = Array.isArray(first) ? first[0] : first;
}

// Flags activés
const trivyEnabled = !!(reportsAvailable.trivy || trivyData.report_path || trivyData.report_url || reports.trivyPath);
const owaspEnabled = !!(reportsAvailable.owasp || owaspData.report_path || owaspData.report_url || reports.owaspPath);
const zapEnabled   = !!(reportsAvailable.zap   || zapData.report_path   || zapData.report_url   || reports.zapPath);

// Paths (priorité: données directes > reports)
const trivyReportPath = trivyData.report_path || trivyData.report_url || reports.trivyPath || null;
const owaspReportPath = owaspData.report_path || owaspData.report_url || reports.owaspPath || null;
const zapReportPath   = zapData.report_path   || zapData.report_url   || reports.zapPath   || null;

return [{
  json: {
    ...incident,
    projectId:  project?.id         || null,
    githubRepo: project?.githubRepo || null,
    projectConfig: {
      cicdTool:       project?.cicdTool       || 'jenkins',
      githubToken:    project?.githubToken    || null,
      jenkinsUrl:     project?.jenkinsUrl     || incident.build_url?.split('/job/')[0] || null,
      jenkinsToken:   project?.jenkinsToken   || null,
      sonarqubeUrl:   project?.sonarqubeUrl   || null,
      sonarqubeKey:   project?.sonarqubeKey   || incident.sonar?.project_key || null,
      sonarqubeToken: project?.sonarqubeToken || null,
      trivyEnabled,
      trivyReportPath,
      dockerImage:    incident.docker?.image  || jenkins.docker?.image_tag || null,
      owaspEnabled,
      owaspReportPath,
      zapEnabled,
      zapTargetUrl:   zapData.target_url      || incident.kubernetes?.target || null,
      zapReportPath,
    }
  }
}];

const incident = $('Extract Project Config').first().json;
const config = incident.projectConfig || {};
const jenkins = incident.jenkins || {};

// Réponse directe de "Send Raw Incident to Backend"
const incidentUUID = $input.first().json.id || null;

// Jenkins config
const jenkinsUrl =
  config.jenkinsUrl ||
  incident.jenkinsUrl ||
  "http://172.31.172.61:8082";

const jobName =
  jenkins.job ||
  config.jenkinsJobName ||
  incident.jenkinsJobName ||
  incident.repository ||
  null  // AUCUN fallback — le job doit être fourni par le webhook;

// Dernière build Jenkins
const buildRef = "lastBuild";

// Sécuriser les slash
const cleanJenkinsUrl = jenkinsUrl.replace(/\/$/, "");

// Si job simple : pfe-app-test
// URL Jenkins : /job/pfe-app-test/lastBuild
const buildBaseUrl =
  `${cleanJenkinsUrl}/job/${jobName}/${buildRef}`;

// Si un path custom existe, on le garde
function resolveReportUrl(customPath, defaultFileName) {
  if (customPath) {
    return customPath
      .replace("{build_url}", `${buildBaseUrl}/`)
      .replace("{jenkins_url}", cleanJenkinsUrl)
      .replace("{job_name}", jobName)
      .replace("{build_number}", buildRef);
  }

  return `${buildBaseUrl}/artifact/${defaultFileName}`;
}

return [
  {
    json: {
      ...incident,

      incidentUUID,

      resolvedUrls: {
        trivy: resolveReportUrl(
          config.trivyReportPath,
          "trivy-report.json"
        ),

        zap: resolveReportUrl(
          config.zapReportPath,
          "zap-report.json"
        ),

        owasp: resolveReportUrl(
          config.owaspReportPath,
          "dependency-check-report.json"
        ),
      },

      fetchFlags: {
        sonarqube: !!(
          config.sonarqubeUrl &&
          config.sonarqubeKey &&
          config.sonarqubeToken
        ),

        trivy: true,
        zap: true,
        owasp: true,
      },
    },
  },
];

// ══════════════════════════════════════════════════════════════
//  MERGE ALL FETCHED DATA — Extract From File (fromJson) + webhook fallback
// ══════════════════════════════════════════════════════════════

// ── Helper : extraire JSON depuis un node Extract From File ──
const parseNodeOutput = (nodeName) => {
  try {
    const item = $(nodeName).first();

    // Cas Extract From File (fromJson) : objet parsé dans json.data
    if (item.json?.data && typeof item.json.data === 'object') {
      return { data: item.json.data, source: 'local_file' };
    }

    // Cas JSON direct (HTTP ou autre)
    if (item.json && !item.json.error && Object.keys(item.json).length > 2) {
      return { data: item.json, source: 'local_file' };
    }

    return { data: null, source: 'none' };
  } catch (e) {
    return { data: null, source: 'error', error: e.message };
  }
};

// ── Sources principales ──
const sonarRaw = $('Fetch SonarQube Issues').first()?.json || {};
const trivyResult = parseNodeOutput('Parse Trivy JSON');
const zapResult = parseNodeOutput('Parse ZAP JSON');
const owaspResult = parseNodeOutput('Parse OWASP JSON');

// ── Fallback webhook ──
const incident = $('Extract Project Config').first().json || {};
const jenkins = incident.jenkins || {};
const webhookTrivy = jenkins.trivy || {};
const webhookZap = jenkins.zap || {};
const webhookOwasp = jenkins.owasp || {};
const webhookTests = jenkins.tests || {};
const incidentUUID = $('Prepare Fetch URLs').first()?.json?.incidentUUID || null;
const projectConfig = incident.projectConfig || {};

// ══════════════════════════════════════════════════════════════
//  SONARQUBE — toujours via API (fiable)
// ══════════════════════════════════════════════════════════════
const sonarIssues = sonarRaw.issues || [];
const sonar = {
  status: sonarIssues.length > 0 ? 'COMPLETED' : 'EMPTY',
  quality_gate: sonarRaw.qualityGate?.status || 'UNKNOWN',
  bugs: sonarIssues.filter(i => i.type === 'BUG').length,
  vulnerabilities: sonarIssues.filter(i => i.type === 'VULNERABILITY').length,
  code_smells: sonarIssues.filter(i => i.type === 'CODE_SMELL').length,
  coverage: Number(sonarRaw.coverage) || 0,
  issues_count: sonarRaw.total || sonarIssues.length,
  issues: sonarIssues.map(i => ({
    key: i.key, rule: i.rule, severity: i.severity,
    component: i.component, project: i.project,
    line: i.line || i.textRange?.startLine,
    message: i.message, type: i.type, effort: i.effort || i.debt,
  })),
};

// ══════════════════════════════════════════════════════════════
//  TRIVY — fichier local > webhook
// ══════════════════════════════════════════════════════════════
const trivyData = trivyResult.data;
const trivyHasData = trivyData && trivyData.Results && !trivyData._source;
let trivyCves = []; let trivyCritical = 0; let trivyHigh = 0;

if (trivyHasData) {
  (trivyData.Results || []).forEach(r => {
    (r.Vulnerabilities || []).forEach(v => {
      if (v.Severity === 'CRITICAL') trivyCritical++;
      if (v.Severity === 'HIGH') trivyHigh++;
      if (['CRITICAL','HIGH','MEDIUM'].includes(v.Severity)) {
        trivyCves.push({
          id: v.VulnerabilityID,
          severity: v.Severity,
          pkg: v.PkgName,
          installedVersion: v.InstalledVersion || '',
          fixedVersion: v.FixedVersion || '',
          title: (v.Title || '').substring(0, 120),
          description: (v.Description || '').substring(0, 400),
          primaryUrl: v.PrimaryURL || '',
          cvss: v.CVSS?.nvd?.V3Score ?? v.CVSS?.redhat?.V3Score ?? null,
          source: 'TRIVY',
        });
      }
    });
  });
} else {
  trivyCritical = webhookTrivy.critical || 0;
  trivyHigh = webhookTrivy.high || 0;
  trivyCves = webhookTrivy.cves || [];
}

const trivy = {
  status: trivyHasData ? 'COMPLETED' : trivyResult.source === 'local_file' ? 'LOCAL' : (trivyCritical + trivyHigh > 0 ? 'WEBHOOK' : 'UNKNOWN'),
  critical: trivyCritical, high: trivyHigh,
  cves_count: trivyCves.length, cves: trivyCves,
  _source: trivyResult.source,
  error: trivyHasData ? '' : 'Fallback: ' + trivyResult.source,
};

// ══════════════════════════════════════════════════════════════
//  ZAP — fichier local > webhook
// ══════════════════════════════════════════════════════════════
const zapData = zapResult.data;
const zapHasData = zapData && zapData.site && !zapData._source && zapData.status !== 'FAILED';
let zapAlerts = []; let zapHigh = 0; let zapMedium = 0; let zapLow = 0;

if (zapHasData) {
  (zapData.site || []).forEach(s => {
    (s.alerts || []).forEach(a => {
      const risk = (a.riskdesc || '').split(' ')[0];
      if (risk === 'High') zapHigh++;
      if (risk === 'Medium') zapMedium++;
      if (risk === 'Low') zapLow++;
      if (zapAlerts.length < 5 && ['High','Medium'].includes(risk)) {
        zapAlerts.push({ name: (a.name || '').substring(0, 60), risk, desc: (a.desc || '').substring(0, 80) });
      }
    });
  });
} else {
  zapHigh = webhookZap.alerts_high || 0;
  zapMedium = webhookZap.alerts_medium || 0;
  zapLow = webhookZap.alerts_low || 0;
  zapAlerts = webhookZap.alerts || [];
}

const zap = {
  status: zapHasData ? 'COMPLETED' : zapResult.source === 'local_file' ? 'LOCAL' : (zapHigh + zapMedium > 0 ? 'WEBHOOK' : 'UNKNOWN'),
  alerts_high: zapHigh, alerts_medium: zapMedium, alerts_low: zapLow,
  alerts_count: zapAlerts.length, alerts: zapAlerts,
  target_url: webhookZap.target_url || projectConfig.zapTargetUrl || '',
  _source: zapResult.source,
  error: zapHasData ? '' : 'Fallback: ' + zapResult.source,
};

// ══════════════════════════════════════════════════════════════
//  OWASP — fichier local > webhook
// ══════════════════════════════════════════════════════════════
const owaspData = owaspResult.data;
const owaspHasData = owaspData && owaspData.dependencies && !owaspData._source;
let owaspCves = []; let owaspCritical = 0; let owaspHigh = 0;

if (owaspHasData) {
  (owaspData.dependencies || []).forEach(dep => {
    (dep.vulnerabilities || []).forEach(v => {
      const sev = (v.severity || '').toUpperCase();
      if (sev === 'CRITICAL') owaspCritical++;
      if (sev === 'HIGH') owaspHigh++;
      if (['CRITICAL','HIGH','MEDIUM'].includes(sev)) {
        owaspCves.push({
          id: v.name,
          severity: sev,
          pkg: dep.fileName,
          installedVersion: dep.version || '',
          fixedVersion: '',
          title: (v.name || ''),
          description: (v.description || '').substring(0, 400),
          primaryUrl: (v.references && v.references[0]?.url) || '',
          cvss: v.cvssv3?.baseScore ?? v.cvssv2?.score ?? null,
          source: 'OWASP',
        });
      }
    });
  });
} else {
  owaspCritical = webhookOwasp.critical || 0;
  owaspHigh = webhookOwasp.high || 0;
  owaspCves = webhookOwasp.cves || [];
}

const owasp = {
  status: owaspHasData ? 'COMPLETED' : owaspResult.source === 'local_file' ? 'LOCAL' : (owaspCritical + owaspHigh > 0 ? 'WEBHOOK' : 'UNKNOWN'),
  critical: owaspCritical, high: owaspHigh,
  cves_count: owaspCves.length, cves: owaspCves,
  _source: owaspResult.source,
  error: owaspHasData ? '' : 'Fallback: ' + owaspResult.source,
};

// ══════════════════════════════════════════════════════════════
//  TESTS + BUILD + DEPLOY + DOCKER
// ══════════════════════════════════════════════════════════════
const tests = {
  total: webhookTests.total || 0, failures: webhookTests.failures || 0,
  skipped: webhookTests.skipped || 0, status: webhookTests.status || 'UNKNOWN',
  coverage: Number(webhookTests.coverage) || 0,
};
const build = {
  job: jenkins.job || incident.job || '', number: jenkins.build_number || incident.build_number || '',
  status: jenkins.status || incident.status || 'UNKNOWN', url: jenkins.build_url || '',
};
const deploy = { status: jenkins.deploy?.status || 'UNKNOWN', app_url: jenkins.deploy?.app_url || '' };
const docker = { image_tag: jenkins.docker?.image || '', build_status: 'UNKNOWN', push_status: 'UNKNOWN' };

// ══════════════════════════════════════════════════════════════
//  OUTPUT
// ══════════════════════════════════════════════════════════════
return [{
  json: {
    enrichedData: { sonar, trivy, zap, owasp, tests, build, deploy, docker },
    incidentUUID,
    projectConfig,
  }
}];

const input = $input.first().json;
const d = input.enrichedData || {};

const systemPrompt = `You are an elite Root Cause Analysis expert for CI/CD DevSecOps pipelines.
Analyze ALL the structured data and identify the main root cause.
Your audience is the DEVELOPER who must fix this: be precise, cite files/lines/rules from the data, never invent evidence.
Return ONLY valid JSON — no markdown, no backticks, no explanation.
SCORING RULES:
- severityScore: integer 1-10 (1=trivial, 10=critical blocker that prevents safe deployment)
- confidence: float 0.0-1.0 based on how complete the scan data is (missing scans lower confidence)
FIELD RULES:
- rootCause: the REAL underlying problem in plain language (not just the symptom)
- evidence: array of concrete references from the data, format "SOURCE | file:line | rule/CVE | short fact"
- whatHappenedForDev: 2-3 sentences explaining to the developer, in simple words, what broke and why the pipeline reacted this way
Return EXACTLY:
{"incidentId":"<id>","errorType":"<type>","rootCause":"<cause>","severityScore":<1-10>,"affectedComponent":"<component>","evidence":["<ref1>","<ref2>"],"whatHappenedForDev":"<plain explanation>","analysisSummary":"<summary>","confidence":<0.0-1.0>}`;

const sonarIssuesCriticalFirst = (() => {
  const all = d.sonar?.issues || [];
  const crit = all.filter(i => ['BLOCKER','CRITICAL'].includes(i.severity));
  const rest = all.filter(i => !['BLOCKER','CRITICAL'].includes(i.severity));
  return JSON.stringify([...crit, ...rest].slice(0, 15));
})();

const userContent = `Root Cause Analysis:
BUILD: ${d.build?.job} #${d.build?.number} — ${d.build?.status}
TESTS: total=${d.tests?.total}, failures=${d.tests?.failures}, status=${d.tests?.status}, coverage=${d.tests?.coverage}%
SONAR: quality_gate=${d.sonar?.quality_gate}, bugs=${d.sonar?.bugs}, vulnerabilities=${d.sonar?.vulnerabilities}, code_smells=${d.sonar?.code_smells}
SONAR ISSUES (${d.sonar?.issues_count} total — showing critical first):
${sonarIssuesCriticalFirst}
TRIVY: status=${d.trivy?.status}, critical=${d.trivy?.critical}, high=${d.trivy?.high}, error="${d.trivy?.error}"
TRIVY CVEs (${d.trivy?.cves_count} total):
${JSON.stringify(d.trivy?.cves?.slice(0,5) || [])}
OWASP: status=${d.owasp?.status}, critical=${d.owasp?.critical}, high=${d.owasp?.high}, error="${d.owasp?.error}"
ZAP: status=${d.zap?.status}, alerts_high=${d.zap?.alerts_high}, error="${d.zap?.error}"
ZAP ALERTS (${d.zap?.alerts_count} total):
${JSON.stringify(d.zap?.alerts?.slice(0,3) || [])}
DEPLOY: status=${d.deploy?.status}, app_url=${d.deploy?.app_url}
DOCKER: build=${d.docker?.build_status}, push=${d.docker?.push_status}, image=${d.docker?.image_tag}`;

const body = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 4000,
  temperature: 0,
  system: systemPrompt,
  messages: [{ role: 'user', content: userContent }]
};

return [{ json: { ollamaBodyString: JSON.stringify(body) } }];

const input = $input.first().json;
const d = input.enrichedData || {};

const systemPrompt = `You are a DevSecOps Security Risk expert.
Analyze ALL security scan results and provide a complete risk assessment.
Your audience is the DEVELOPER: for each major vulnerability explain concretely HOW it could be exploited and WHAT the business impact is, so the fix priority is obvious.
Return ONLY valid JSON — no markdown, no backticks, no explanation.
SCORING RULES:
- riskScore: integer 0-100 (0=no risk, 100=actively exploitable critical vulnerability)
- riskLevel: one of LOW | MEDIUM | HIGH | CRITICAL, derived from riskScore (0-25=LOW, 26-50=MEDIUM, 51-75=HIGH, 76-100=CRITICAL)
- safeToApply: true ONLY if no CRITICAL/HIGH CVE is present
- confidence: 0.0-1.0; lower it when scans returned UNKNOWN status
FIELD RULES:
- vulnerabilities: array of objects, one per major finding (max 8), each with:
  {"ref":"CVE-XXXX or rule key","source":"TRIVY|OWASP|ZAP|SONARQUBE","severity":"...","component":"file/lib/endpoint","exploitScenario":"1-2 sentences: how an attacker abuses this","impact":"what happens if exploited","fixHint":"the single most effective fix action"}
Return EXACTLY:
{"incidentId":"<id>","riskLevel":"<LEVEL>","riskScore":<0-100>,"vulnerabilities":[{...}],"safeToApply":<bool>,"securitySummary":"<summary>","confidence":<0.0-1.0>}`;

const sonarVulnsCriticalFirst = (() => {
  const all = (d.sonar?.issues || []).filter(i => i.type === 'VULNERABILITY');
  const crit = all.filter(i => ['BLOCKER','CRITICAL'].includes(i.severity));
  const rest = all.filter(i => !['BLOCKER','CRITICAL'].includes(i.severity));
  return JSON.stringify([...crit, ...rest].slice(0, 10));
})();

const userContent = `Security Risk Analysis:
BUILD: ${d.build?.job} #${d.build?.number} — ${d.build?.status}
TRIVY CONTAINER SCAN:
  status: ${d.trivy?.status}, critical: ${d.trivy?.critical}, high: ${d.trivy?.high}
  error: "${d.trivy?.error}"
  CVEs (${d.trivy?.cves_count}):
  ${JSON.stringify(d.trivy?.cves?.slice(0,10) || [])}
OWASP DEPENDENCY CHECK:
  status: ${d.owasp?.status}, critical: ${d.owasp?.critical}, high: ${d.owasp?.high}
  CVEs: ${JSON.stringify(d.owasp?.cves?.slice(0,5) || [])}
ZAP DAST SCAN:
  status: ${d.zap?.status}, alerts_high: ${d.zap?.alerts_high}, alerts_medium: ${d.zap?.alerts_medium}
  target: ${d.zap?.target_url}, error: "${d.zap?.error}"
  Alerts: ${JSON.stringify(d.zap?.alerts?.slice(0,5) || [])}
SONAR SECURITY:
  vulnerabilities: ${d.sonar?.vulnerabilities}, quality_gate: ${d.sonar?.quality_gate}
  Security Issues (critical first): ${sonarVulnsCriticalFirst}`;

const body = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 4000,
  temperature: 0,
  system: systemPrompt,
  messages: [{ role: 'user', content: userContent }]
};

return [{ json: { ollamaBodyString: JSON.stringify(body) } }];

const input = $input.first().json;
const d = input.enrichedData || {};

const systemPrompt = `You are a DevSecOps Remediation Engineer.
Analyze the pipeline data and provide ONE remediation plan covering the most critical issues.
ABSOLUTE RULES:
- Return ONLY a single raw JSON object
- NO array, NO markdown, NO backticks, NO code blocks, NO escaped JSON strings
- Start your response with { and end with }
- Each fixStep is a short actionable command (max 120 chars)
- Maximum 4 fixSteps
autoFixable DECISION RULE (critical — this drives the platform recommendation):
- Set autoFixable=true ONLY if ALL issues can be fixed by editing source files without architectural changes, new dependencies, or secret/infra migration.
