const confidenceScore = rawConf > 1 ? rawConf / 100 : rawConf;

const incidentId = final.incidentUUID || merged.incidentUUID || null;

return [{
  json: {
    incidentId,
    incidentUUID:     incidentId,
    projectId:        cfg.projectId || final.projectId || null,
    githubRepo,
    githubToken:      cfg.projectConfig?.githubToken || null,
    branch:           'main',
    default_branch:   'main',
    decision:         (judge.decision || 'NOTIFY_ONLY').toUpperCase(),
    confidenceScore,
    riskLevel:        (judge.securityLevel || 'HIGH').toLowerCase(),
    aiAnalysis:       judge,
    developerGuide:   devGuide,
    jenkinsJobName:   cfg.job || cfg.jenkinsJobName || enriched.build?.job || null,
    buildNumber:      enriched.build?.number || cfg.build_number || null,
    enrichedData:     enriched,
    repository_owner: repoOwner,
    repository_name:  repoName,
    target_file_path: targetFile,
  }
}];

const input = $input.first().json;
const d = input.enrichedData || {};

const systemPrompt = `Tu es l'agent DEVELOPER GUIDANCE d'une plateforme DevSecOps IA.
Ta seule mission : faciliter la vie du développeur. Pour CHAQUE problème significatif trouvé par les scanners, tu produis une fiche de correction prête à suivre.
Réponds UNIQUEMENT en JSON valide — pas de markdown, pas de backticks, pas d'explication. Commence par { et termine par }.
LANGUE : les champs summaryForDeveloper, title, problem, whyItMatters, howToFix et resolutionHint sont rédigés en FRANÇAIS clair et professionnel. Les termes techniques, noms de règles, commandes et extraits de code restent en anglais.

SÉLECTION DES PROBLÈMES (dans cet ordre, max 15 au total, couvre TOUS les outils qui ont des findings) :
1. Tous les SonarQube BLOCKER et CRITICAL (bugs + vulnérabilités + code smells CRITICAL)
2. Toutes les CVE CRITICAL/HIGH de Trivy et OWASP Dependency-Check (déduplique par CVE id, garde une entrée par CVE avec la liste des packages affectés)
3. Les alertes ZAP High puis Medium
4. Les échecs de tests et de build/deploy
5. Les bugs SonarQube MAJOR s'il reste de la place

POUR CHAQUE PROBLÈME, TOUS LES CHAMPS SONT OBLIGATOIRES :
- id : référence courte unique ("SONAR-1", "CVE-2024-1234", "ZAP-1", "TEST-1", "BUILD-1")
- source : SONARQUBE | TRIVY | OWASP | ZAP | TESTS | BUILD
- category : CODE (fichier source) | DEPENDENCY (pom.xml/lib) | CONTAINER (image Docker) | DAST (runtime web) | TESTS | BUILD
- severity : BLOCKER | CRITICAL | HIGH | MAJOR | MEDIUM
- title : nom du problème en une ligne (français)
- file : chemin exact du fichier depuis les données (retire le préfixe "projectKey:"). "pom.xml" pour les dépendances, "Dockerfile" pour l'image conteneur, "N/A" seulement si vraiment inconnu
- line : numéro de ligne (entier) depuis les données, ou 0
- rule : clé de règle SonarQube, id CVE, ou nom d'alerte ZAP
- problem : le VRAI problème expliqué en français simple qu'un développeur junior comprend (2-3 phrases). Pas le symptôme — la cause.
- whyItMatters : risque concret si non corrigé (exploitation, crash, perte de données…), en français
- howToFix : tableau de 2-5 étapes ordonnées et actionnables en français : quel fichier ouvrir, quoi changer, quelle commande lancer
- codeExample : {"before":"<extrait vulnérable reconstruit depuis la règle et le contexte>","after":"<extrait corrigé>"} — max 300 caractères chacun ; "" si non applicable
- verification : commande ou action exacte prouvant que le fix marche (ex: "mvn test", "mvn org.owasp:dependency-check-maven:check", "relancer le job Jenkins et vérifier le quality gate")
- estimatedEffortMinutes : entier réaliste
- priority : entier 1..N (1 = à corriger en premier). Ordre : sécurité exploitable > blockers > bugs > reste

CHAMPS GLOBAUX :
- summaryForDeveloper : 3-4 phrases en français : ce qui est cassé globalement et le plan d'attaque recommandé
- quickWins : tableau des ids corrigeables en moins de 15 min (max 3)
- fixOrder : tableau de TOUS les ids dans l'ordre recommandé
- totalEstimatedMinutes : somme des efforts
- confidence : 0.0-1.0

Retourne EXACTEMENT :
{"incidentId":"<id>","summaryForDeveloper":"...","issues":[{...}],"quickWins":["..."],"fixOrder":["..."],"totalEstimatedMinutes":<int>,"confidence":<0.0-1.0>}`;

// ── Sélection des données : sévère d'abord, budget token maîtrisé ──
const sonarAll = d.sonar?.issues || [];
const sevOrder = { BLOCKER: 0, CRITICAL: 1, MAJOR: 2, MINOR: 3, INFO: 4 };
const sonarSorted = [...sonarAll].sort((a, b) =>
  (sevOrder[a.severity] ?? 9) - (sevOrder[b.severity] ?? 9)
).slice(0, 20).map(i => ({
  key: i.key, rule: i.rule, severity: i.severity, type: i.type,
  component: i.component, line: i.line, message: i.message
}));

// Dédupliquer les CVE par id, sévère d'abord, champs compacts
const compactCve = (c) => ({
  id: c.id, severity: c.severity, pkg: c.pkg,
  installedVersion: c.installedVersion || '', fixedVersion: c.fixedVersion || '',
  title: (c.title || '').substring(0, 100), cvss: c.cvss ?? null,
});
const dedupe = (arr) => {
  const seen = new Map();
  for (const c of arr) {
    if (!seen.has(c.id)) seen.set(c.id, compactCve(c));
    else {
      const prev = seen.get(c.id);
      if (c.pkg && !prev.pkg.includes(c.pkg)) prev.pkg += ', ' + c.pkg;
    }
  }
  return [...seen.values()];
};
const cveSort = (a, b) => ({CRITICAL:0,HIGH:1,MEDIUM:2}[a.severity] ?? 9) - ({CRITICAL:0,HIGH:1,MEDIUM:2}[b.severity] ?? 9) || (b.cvss ?? 0) - (a.cvss ?? 0);
const trivyCves = dedupe(d.trivy?.cves || []).sort(cveSort).slice(0, 12);
const owaspCves = dedupe(d.owasp?.cves || []).sort(cveSort).slice(0, 10);
const zapAlerts = (d.zap?.alerts || []).slice(0, 6);

const userContent = `Génère le guide de correction développeur pour cet incident de pipeline.
INCIDENT: ${input.incidentUUID || d.build?.job || 'unknown'}
BUILD: ${d.build?.job} #${d.build?.number} — status=${d.build?.status}
TESTS: total=${d.tests?.total}, failures=${d.tests?.failures}, status=${d.tests?.status}, coverage=${d.tests?.coverage}%
SONARQUBE: quality_gate=${d.sonar?.quality_gate}, bugs=${d.sonar?.bugs}, vulnerabilities=${d.sonar?.vulnerabilities}, code_smells=${d.sonar?.code_smells}
SONAR ISSUES (sévères d'abord, ${d.sonar?.issues_count ?? sonarAll.length} au total):
${JSON.stringify(sonarSorted)}
TRIVY (conteneur): status=${d.trivy?.status}, critical=${d.trivy?.critical}, high=${d.trivy?.high}, total_cves=${d.trivy?.cves_count}
TRIVY CVEs (dédupliquées, sévères d'abord): ${JSON.stringify(trivyCves)}
OWASP DEPENDENCY-CHECK: status=${d.owasp?.status}, critical=${d.owasp?.critical}, high=${d.owasp?.high}, total_cves=${d.owasp?.cves_count}
OWASP CVEs (dédupliquées): ${JSON.stringify(owaspCves)}
ZAP DAST: status=${d.zap?.status}, alerts_high=${d.zap?.alerts_high}, alerts_medium=${d.zap?.alerts_medium}, target=${d.zap?.target_url}
ZAP ALERTS: ${JSON.stringify(zapAlerts)}
DOCKER: build=${d.docker?.build_status}, image=${d.docker?.image_tag}
DEPLOY: status=${d.deploy?.status}`;

const body = {
  model: 'claude-sonnet-4-6',
  max_tokens: 7000,
  temperature: 0,
  system: systemPrompt,
  messages: [{ role: 'user', content: userContent }]
};

return [{ json: { ollamaBodyString: JSON.stringify(body) } }];

const response = $input.first().json;
const content = response.content?.[0]?.text || '';
const fallback = (reason, raw) => [{ json: {
  incidentId: 'unknown', summaryForDeveloper: reason,
  issues: [], quickWins: [], fixOrder: [], totalEstimatedMinutes: 0,
  confidence: 0.0, parseError: true, raw: (raw || '').substring(0, 500)
}}];
if (!content) return fallback('Developer Guidance agent returned empty response', '');
let clean = content.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
const start = clean.indexOf('{'); const end = clean.lastIndexOf('}');
if (start === -1 || end === -1) return fallback('No JSON found in agent output', clean);
try {
  const parsed = JSON.parse(clean.substring(start, end + 1));
  parsed.issues = Array.isArray(parsed.issues) ? parsed.issues : [];
  // Tri de sécurité : toujours par priorité croissante
  parsed.issues.sort((a, b) => (a.priority ?? 99) - (b.priority ?? 99));
  return [{ json: parsed }];
} catch (e) {
  return fallback('JSON parse failed: ' + e.message, clean);
}
